   140     // CSV spec: https://www.ietf.org/rfc/rfc4180.txt
   141     // Quotes are escaped via double quotes
   142
   143     template <string_t T>
   144     struct from<CSV, T>
   145     {
   146        template <auto Opts, class It>
   147        static void op(auto&& value, is_context auto&& ctx, It&& it, auto&& end)
   148        {
   149           if (bool(ctx.error)) [[unlikely]] {
   150              return;
   151           }
   152
   153           value.clear();
   154
   155           if (it == end) {
   156              return;
   157           }
   158
   159           if (*it == '"') {
   160              // Quoted field
   161              ++it; // Skip the opening quote
   162
   163              if constexpr (check_raw_string(Opts)) {
   164                 // Raw string mode: don't process escape sequences
   165                 while (it != end) {
   166                    if (*it == '"') {
   167                       ++it; // Skip the quote
   168                       if (it == end || *it != '"') {
   169                          // Single quote - end of field
   170                          break;
   171                       }
   172                       // Double quote - add one quote and continue
   173                       value.push_back('"');
   174                       ++it;
   175                    }
   176                    else {
   177                       value.push_back(*it);
   178                       ++it;
   179                    }
   180                 }
   181              }
   182              else {
   183                 // Normal mode: process escape sequences properly
   184                 while (it != end) {
   185                    if (*it == '"') {
   186                       ++it; // Skip the quote
   187                       if (it == end) {
   188                          // End of input after closing quote
   189                          break;
   190                       }
   191                       if (*it == '"') {
   192                          // Escaped quote
   193                          value.push_back('"');
   194                          ++it;
   195                       }
   196                       else {
   197                          // Closing quote
   198                          break;
   199                       }
   200                    }
   201                    else {
   202                       value.push_back(*it);
   203                       ++it;
   204                    }
   205                 }
   206              }
   207
   208              // After closing quote, expect comma, newline, or end of input
   209              if (it != end && *it != ',' && *it != '\n' && *it != '\r') {
   210                 // Invalid character after closing quote
   211                 ctx.error = error_code::syntax_error;
   212                 return;
   213              }
   214           }
   215           else {
   216              // Unquoted field
   217              while (it != end && *it != ',' && *it != '\n' && *it != '\r') {
   218                 value.push_back(*it);
   219                 ++it;
   220              }

